// top -- mythrv32 board top for Colorlight 5a-75b v8.2 (LFE5U-25F CABGA256).
//
// Pin facts (~/dev/project/chubby75/5a-75b/hardware_V8.2.md, verified):
//   clk_i      P6   25 MHz, generated by phy1 (U13) -- the PHYs must NEVER
//                    be reset while gateware depends on this clock;
//                    phy_rst_n is driven HIGH here for that reason.
//   key_i      R7   KEY+ button: pressed reads LOW (10k pull-up, V7.0 doc).
//   led_o      T6   DATA_LED-: active low (sourcing; docs suggest open drain
//                    -- we use ~enable: lit when the net is low).
//   uart_txd   C4   J1-1, wired to the USB-serial adapter (/dev/ttyUSB0).
//   uart_rxd   D4   J1-2; adapter must cross TX<->RX, else keep pulled-up
//                    idle via the LPF (idle line = no RX irqs).
//   SDRAM U29 (M12L64322A, 2Mx32): pads per design.md sec.2/6a; CS#/CKE/
//                    DQM0..3 are hard-wired on the board -> wb_sdram drives
//                    their outputs internally, no pads here (see lpf).
//   JTAG: dedicated ECP5 pins (header J27/J31/J32/J30) -> no IO in this top.
//
// SDRAM clock (C8): ODDRX1F toggling the pad every clk edge with SCLK = clk
//   -> pad CK rising edges are ALIGNED with internal clk posedges, which is
//   exactly the cycle convention wb_sdram was verified against (sec.6a:
//   command visible cycle d+1, device latches edge CLOSING d+1 = next rising
//   pad edge; full-period setup at 25 MHz). nextpnr-ecp5 requires ODDRX1F Q
//   to drive a top-level port directly (ecp5/pack.cc) -- done below.
//   DQ: one $_TBUF_-inferable assign per bit (oe ? drv : 'z').
//
// Simulation of the SoC uses tb/tb_soc.v + DRAM_SDRAM=0 (wb_ram); the board
// path (this file) is proven by synthesis/P&R + on-hardware runs, the
// wb_sdram logic itself by tb/tb_wb_sdram.v against a timing device model.
`default_nettype none

module top #(
    parameter ROM_HEX  = "tb/t_fw_demo.hex",  // synthesized into the BRAM ROM
    parameter integer ROM_DEPTH = 8192,       // ROM words (synth variant: small)
    parameter integer LINES_I = 1024,         // I$ lines (synth variant: 64)
    parameter integer LINES_D = 1024,         // D$ lines (synth variant: 64)
    parameter UART_CLK = 25_000_000,
    parameter UART_BAUD = 115_200
)(
    input  wire        clk_i,
    input  wire        key_i,
    output wire        led_o,
    output wire        phy_rst_n,
    output wire        uart_txd,
    input  wire        uart_rxd,

    output wire        sd_clk_o,
    output wire [10:0] sd_a_o,   // 11 physical lines; a_r[12:11] const 0
    output wire [1:0]  sd_ba_o,
    output wire        sd_ras_n_o,
    output wire        sd_cas_n_o,
    output wire        sd_we_n_o,
    inout  wire [31:0] sd_dq_io
);

    // ------------------------------------------------- reset (POR + key)
    reg [15:0] por_cnt = 16'd0;
    reg [2:0]  key_sync = 3'b111;
    always @(posedge clk_i) begin
        if (!&por_cnt) por_cnt <= por_cnt + 16'd1;
        key_sync <= {key_sync[1:0], key_i};
    end
    wire rst = ~(&por_cnt) | ~key_sync[2];   // active-high, synced to clk_i
    // POR holds ~2.6 ms > wb_sdram T_INIT (200 us, sec.6a); key held down
    // keeps the whole SoC in reset (wb_sdram re-inits, refresh counters reset).

    // ------------------------------------------------------ heartbeat LED
    reg [24:0] hb = 25'd0;
    always @(posedge clk_i) hb <= hb + 25'd1;
    assign led_o = ~hb[23];      // active low: ~1.49 Hz blink
    assign phy_rst_n = 1'b1;     // keep phy1 alive: it drives clk_i (P6)

    // ------------------------------------------------------------- SoC
    wire [1:0]  sd_ba;
    wire [12:0] sd_a;            // controller drives 13; only [10:0] exist on U29
    wire        sd_ras_n, sd_cas_n, sd_we_n;
    wire [31:0] sd_dq_drv;
    wire        sd_oe;

    soc #(
        .ROM_DEPTH(ROM_DEPTH), .ROM_HEX(ROM_HEX),
        .UART_CLK(UART_CLK), .UART_BAUD(UART_BAUD),
        .CLK_HZ(UART_CLK), .DRAM_SDRAM(1),
        .LINES_I(LINES_I), .LINES_D(LINES_D)
    ) soc0 (
        .clk(clk_i), .rst(rst),
        .uart_rxd(uart_rxd), .uart_txd(uart_txd),
        .sd_ba_o(sd_ba), .sd_a_o(sd_a),
        .sd_ras_n_o(sd_ras_n), .sd_cas_n_o(sd_cas_n), .sd_we_n_o(sd_we_n),
        .sd_cs_n_o(), .sd_cke_o(), .sd_dqm_o(),   // hard-wired on v8.2
        .sd_dq_o(sd_dq_drv), .sd_dq_oe_o(sd_oe), .sd_dq_i(sd_dq_io)
    );

    assign sd_a_o   = sd_a[10:0];   // a_r[12:11] never asserted (const 0)
    assign sd_ba_o  = sd_ba;
    assign sd_ras_n_o = sd_ras_n;
    assign sd_cas_n_o = sd_cas_n;
    assign sd_we_n_o  = sd_we_n;

    // SDRAM clock: pad toggles 1,0 per clk edge -> 25 MHz CK in phase with
    // the internal clock (rising on posedge clk). Open-drain-safe constant.
    ODDRX1F sd_clk_drv (
        .SCLK(clk_i), .RST(1'b0), .D0(1'b1), .D1(1'b0), .Q(sd_clk_o)
    );

    // DQ: bit-level tristate (yosys maps to $_TBUF_, nextpnr to SB_IO OE).
    genvar b;
    generate
        for (b = 0; b < 32; b = b + 1) begin : g_dq
            assign sd_dq_io[b] = sd_oe ? sd_dq_drv[b] : 1'bz;
        end
    endgenerate

endmodule
`default_nettype wire
